using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using Nexora.Demo.Desktop.Features.Packages.Models;

namespace Nexora.Demo.Desktop.Features.Packages.Services;

public static class DemoPackageStore
{
    private static readonly string StorePath = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "NexoraProductDemo", "service-package-catalog-v1.json");

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        WriteIndented = true,
        PropertyNameCaseInsensitive = true
    };

    public static DemoPackageCatalog Load()
    {
        var directory = Path.GetDirectoryName(StorePath)!;
        Directory.CreateDirectory(directory);

        if (!File.Exists(StorePath))
        {
            var seeded = CreateSeedCatalog();
            Save(seeded);
            return seeded;
        }

        try
        {
            var json = File.ReadAllText(StorePath);
            var catalog = JsonSerializer.Deserialize<DemoPackageCatalog>(json, JsonOptions);
            if (catalog is null || catalog.Packages is null || catalog.Bindings is null)
                throw new InvalidDataException("ملف كتالوج الباقات لا يحتوي على بيانات صالحة.");

            catalog.Packages ??= new List<DemoServicePackage>();
            catalog.Bindings ??= new List<DemoPackageBinding>();
            foreach (var binding in catalog.Bindings)
                binding.AccessDays ??= new List<string>();
            return catalog;
        }
        catch (JsonException ex)
        {
            throw new InvalidDataException(
                "تعذر قراءة ملف بيانات الباقات. لم يتم استبدال الملف حفاظًا على سلامة البيانات.", ex);
        }
    }

    public static void Save(DemoPackageCatalog catalog)
    {
        ArgumentNullException.ThrowIfNull(catalog);
        var directory = Path.GetDirectoryName(StorePath)!;
        Directory.CreateDirectory(directory);
        var tempPath = StorePath + ".tmp";
        var json = JsonSerializer.Serialize(catalog, JsonOptions);
        File.WriteAllText(tempPath, json);
        File.Move(tempPath, StorePath, true);
    }

    private static DemoPackageCatalog CreateSeedCatalog()
    {
        var catalog = new DemoPackageCatalog();
        var allDays = new List<string> { "السبت", "الأحد", "الإثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة" };

        // Seed names, prices, limits and provider profile identifiers are kept aligned with the planned card-demo catalog.
        var hour = NewPackage("pkg-hour-basic", "ساعة واحدة", 1, 1, 0, 500, "MB", 2m, 2m, 100m);
        var sixHours = NewPackage("pkg-six-hours", "6 ساعات", 3, 6, 0, 2, "GB", 4m, 4m, 300m);
        var daily = NewPackage("pkg-day-pass", "24 ساعة", 7, 24, 0, 5, "GB", 6m, 6m, 500m);
        var weekly = NewPackage("pkg-weekly", "أسبوع", 7, 168, 0, 20, "GB", 8m, 8m, 1500m);
        catalog.Packages.AddRange(new[] { hour, sixHours, daily, weekly });

        catalog.Bindings.Add(NewHotSpotBinding("bind-hotspot-hour", hour.Id, "HS-1H-500M", "hotspot1", 1));
        catalog.Bindings.Add(NewHotSpotBinding("bind-hotspot-six", sixHours.Id, "HS-6H-2G", "hotspot1", 1, true, "UM-6H-2G"));
        catalog.Bindings.Add(NewHotSpotBinding("bind-hotspot-day", daily.Id, "HS-24H-5G", "all", 1, true, "UM-24H-5G"));
        catalog.Bindings.Add(NewHotSpotBinding("bind-hotspot-week", weekly.Id, "HS-7D-20G", "all", 1, true, "UM-7D-20G"));

        catalog.Bindings.Add(NewUserManagerBinding("bind-um-hour", hour.Id, "UM-1H-500M", "default", "first-auth", allDays));
        catalog.Bindings.Add(NewUserManagerBinding("bind-um-six", sixHours.Id, "UM-6H-2G", "default", "first-auth", allDays));
        catalog.Bindings.Add(NewUserManagerBinding("bind-um-day", daily.Id, "UM-24H-5G", "retailers", "assigned", allDays));
        catalog.Bindings.Add(NewUserManagerBinding("bind-um-week", weekly.Id, "UM-7D-20G", "retailers", "assigned", allDays));
        return catalog;
    }

    private static DemoServicePackage NewPackage(
        string id, string name, int validityDays, int uptimeHours, int uptimeMinutes,
        decimal quota, string quotaUnit, decimal downloadMbps, decimal uploadMbps, decimal salePrice)
    {
        return new DemoServicePackage
        {
            Id = id,
            Name = name,
            ValidityDays = validityDays,
            UnlimitedValidity = false,
            UptimeHours = uptimeHours,
            UptimeMinutes = uptimeMinutes,
            DataQuotaAmount = quota,
            DataQuotaUnit = quotaUnit,
            UnlimitedData = false,
            DownloadMbps = downloadMbps,
            UploadMbps = uploadMbps,
            SalePriceYer = salePrice,
            CardDisplayPriceYer = salePrice,
            CommissionEnabled = false,
            CommissionMode = "Percentage",
            CommissionValue = 0,
            PreserveUsageOnRouterInterruption = true,
            PreserveTimeOnRouterInterruption = true,
            RecordHotSpotSessions = true,
            NotificationsEnabled = true,
            FirstAlertPercent = 70,
            SecondAlertPercent = 95,
            Notes = string.Empty,
            CreatedAt = DateTimeOffset.Now,
            UpdatedAt = DateTimeOffset.Now
        };
    }

    private static DemoPackageBinding NewHotSpotBinding(string id, string packageId, string profile, string server, int sharedUsers, bool useUserManager = false, string? userManagerProfile = null)
        => new()
        {
            Id = id, PackageId = packageId, ProviderKey = "hotspot",
            HotSpotProfile = profile, HotSpotServer = server, HotSpotSharedUsers = sharedUsers,
            HotSpotUsesUserManager = useUserManager,
            HotSpotUserManagerProfile = userManagerProfile ?? "UM-1H-500M",
            IsEnabled = true, CreatedAt = DateTimeOffset.Now, UpdatedAt = DateTimeOffset.Now
        };

    private static DemoPackageBinding NewUserManagerBinding(string id, string packageId, string profile, string group, string startsWhen, List<string> days)
        => new()
        {
            Id = id, PackageId = packageId, ProviderKey = "user-manager",
            UserManagerProfile = profile, UserManagerGroup = group,
            UserManagerLimitation = packageId == "pkg-hour-basic" ? "limit-hour-500mb-2m" : packageId == "pkg-six-hours" ? "limit-six-hours-2gb-4m" : packageId == "pkg-day-pass" ? "limit-daily-5gb-6m" : "limit-weekly-20gb-8m",
            UserManagerStartsWhen = startsWhen, UserManagerSharedOverride = "off",
            UseSchedule = false, AccessDays = new List<string>(days),
            AccessFrom = "00:00", AccessUntil = "23:59",
            IsEnabled = true, CreatedAt = DateTimeOffset.Now, UpdatedAt = DateTimeOffset.Now
        };
}